import subprocess, re, datetime, sys

REPO = "/tmp/shurik-workspace-LmSYFO"
def git(*args):
    return subprocess.check_output(["git","-C",REPO]+list(args), text=True)

def commit_meta(sha):
    out = git("show", sha, "--format=%cI").strip()
    dt = datetime.datetime.fromisoformat(out).astimezone(datetime.timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def utterance(sha):
    body = git("show", sha, "--format=%B")
    blocks = body.rstrip("\n").split("\n\n")
    for b in reversed(blocks):
        if re.match(r"^[A-Z][A-Za-z]*: ", b):
            return b.rstrip("\n")
    raise SystemExit("no utterance in "+sha)

def entry(sha, branch, speaker, ts):
    return f"**{speaker}** ({ts})\n\nSource: {branch} @ {sha}\n\n{utterance(sha)}\n"

